function getImageDimensions(buf) {
  // JPEG: scan markers for a Start-Of-Frame segment (SOF0-3) which holds height/width.
  if (buf.length > 4 && buf[0] === 0xFF && buf[1] === 0xD8) {
    let offset = 2;
    while (offset + 9 < buf.length) {
      if (buf[offset] !== 0xFF) { offset++; continue; }
      const marker = buf[offset + 1];
      if (marker >= 0xC0 && marker <= 0xC3) {
        return { width: buf.readUInt16BE(offset + 7), height: buf.readUInt16BE(offset + 5) };
      }
      const segLength = buf.readUInt16BE(offset + 2);
      offset += 2 + segLength;
    }
    return null;
  }
  // PNG: IHDR chunk is always the first chunk, right after the 8-byte signature.
  if (buf.length > 24 && buf[0] === 0x89 && buf[1] === 0x50) {
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  return null; // WEBP dimension parsing not implemented - skip the resolution check for it.
}

const MIN_DIMENSION = 720; // yeu cau anh that >=720p (theo chieu nho hon)

// Lay scene tu node 'Check Tavily Images' (KHONG phai $input.item.json) vi
// Download Image (Tavily) co the that bai (timeout/mat ket noi) va van tiep
// tuc chay (onError=continueRegularOutput) voi json bi thay the (vd {error}),
