// !!! DOI duong dan SUBSCRIBE_CLIP cho dung may ban neu can !!!
// !!! DOI SCENE_TIMEOUT_SEC neu may ban render cham/nhanh hon muc mac dinh !!!
// Dinh dang SHORTS doc 9:16 (1080x1920)
const W = 1080, H = 1920, FPS = 30;
// FIX (chuyen canh/zoom bi rung lac nhe - zoompan jitter): filter 'zoompan'
// cua ffmpeg lam tron x/y ve so nguyen MOI FRAME. Voi zoom cham (vd +0.0008/
// frame), buoc di chuyen thuc te duoi 1 pixel/frame nen bi lam tron thanh cac
// buoc nhay 0-hoac-1-pixel khong deu, tao cam giac 'giat/rung' nhe (da kiem
// chung: do coefficient-of-variation cua frame-diff giam ~50% khi supersample
// 2x roi downscale, so voi lam zoompan truc tiep o do phan giai dich). Cach
// khac phuc chuan: cho zoompan chay tren canvas LON HON (SS lan), roi scale
// xuong kich thuoc that o buoc cuoi - luoi pixel min hon lam sai so lam tron
// tro nen nho hon nhieu (duoi nguong nhin thay) sau khi downscale.
const SS = 2;
const WS = W * SS, HS = H * SS;
const SCENE_TIMEOUT_SEC = 300;
const PRESET = 'veryfast';
const staticData = $getWorkflowStaticData('global');
const scenes = (staticData.scenes || []).slice().sort((a, b) => a.sceneId - b.sceneId);
const videoId = $('Generate Video ID').first().json.videoId;
const dir = $('Init Paths').first().json.videoDir;
const subscribeClip = $('Init Paths').first().json.subscribeClip;

function zoompanExpr(camera) {
  switch (camera) {
    case 'push-in':
      return `zoompan=z='min(1+0.20*on/$FRAMES,1.20)':d=$FRAMES:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
    case 'pull-out':
      return `zoompan=z='max(1.20-0.20*on/$FRAMES,1.0)':d=$FRAMES:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
    case 'pan-left':
      return `zoompan=z=1.15:d=$FRAMES:x='(iw-iw/zoom)*(1-on/$FRAMES)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
    case 'pan-right':
      return `zoompan=z=1.15:d=$FRAMES:x='(iw-iw/zoom)*(on/$FRAMES)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
    case 'parallax':
      return `zoompan=z='min(zoom+0.0010,1.25)':d=$FRAMES:x='(iw-iw/zoom)*(on/$FRAMES)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
    case 'slow-zoom':
    default:
      // FIX (khong con 'static' khong zoom): moi scene LUON co Ken Burns zoom nhe,
      // ke ca khi model tra ve gia tri camera khong xac dinh.
      return `zoompan=z='min(zoom+0.0008,1.15)':d=$FRAMES:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=${WS}x${HS}:fps=${FPS}`;
  }
}

// Bo chu (caption) chay theo giong doc: dung dinh dang ASS (khong phai SRT) voi
