  'Style: Default,Arial,46,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,3,1,2,60,60,140,1',
  '',
  '[Events]',
  'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text'
].join('\n');

function cleanCaption(text) {
  return String(text || '').trim().replace(/\s+/g, ' ');
}
// Escape ky tu dac biet cua ASS ({ } co the bi hieu nham la override tag) roi
// den ky tu dac biet cua bash heredoc KHONG quote ($ va backtick) - can de
// SUB_START/SUB_END van duoc noi suy binh thuong trong heredoc.
function escapeForHeredoc(text) {
  return String(text)
    .replace(/\\/g, '\\\\')
    .replace(/\{/g, '(').replace(/\}/g, ')')
    .replace(/`/g, '\\`').replace(/\$/g, '\\$');
}

let script = `#!/bin/bash
set -e
# ffmpeg chuan cua Homebrew KHONG co libass/freetype (thieu filter 'ass').
# Uu tien dung ffmpeg-full (co libass) neu da cai, fallback ve ffmpeg mac dinh.
if [ -d "/opt/homebrew/opt/ffmpeg-full/bin" ]; then
  export PATH="/opt/homebrew/opt/ffmpeg-full/bin:$PATH"
fi
cd "${dir}"

exec 2>> "${dir}/ffmpeg_error.log"

PROGRESS_LOG="${dir}/render_progress.log"
> "$PROGRESS_LOG"

SUBTITLE_FILE="${dir}/subtitles.ass"
cat > "$SUBTITLE_FILE" << 'ASSHEADEREOF'
${assHeader}
ASSHEADEREOF
SUB_OFFSET=0

SUBSCRIBE_SRC="${subscribeClip}"
SUBSCRIBE_NORMALIZED="${dir}/subscribe_normalized.mp4"
